@Override protected void onResponse(StreamingCommitResponse response){
  commitWorkThrottleTimer.stop();
  for (int i=0; i < response.getRequestIdCount(); ++i) {
    try {
      long requestId=response.getRequestId(i);
      PendingRequest done=pending.remove(requestId);
      if (done == null) {
        LOG.error("Got unknown commit request ID: {}",requestId);
      } else {
        done.onDone.accept((i < response.getStatusCount()) ? response.getStatus(i) : CommitStatus.OK);
      }
    } catch (java.lang.UnsupportedOperationException | java.lang.ClassCastException e) {
      LOG.error("Failed to process commit request ID: {}", requestId, e);
    }
  }
}
